23:   'use strict';
24: 
25:   // ---------------------------------------------------------------------------
26:   // 1. Constants & Configuration
27:   // ---------------------------------------------------------------------------
28:   var CONSTANTS = Object.freeze({
29:     SAFE_X_MIN: 96,
30:     SAFE_X_MAX: 1824, // 1920 - 96
31:     SAFE_Y_MIN: 54,
32:     SAFE_Y_MAX: 1026, // 1080 - 54
33:     HEADER_HEIGHT: 84,
34:     EFFECTIVE_Y_MIN: 104, // 84 + 20px buffer
35:     PEEK_OFFSET: 48,
36:     THROTTLE_INTERVAL: 60
37:   });
38: 
39:   var KEY_CODES = Object.freeze({
40:     UP: [38],
41:     DOWN: [40],
42:     LEFT: [37],
43:     RIGHT: [39],
44:     ENTER: [13],
45:     BACK: [461, 27],
46:     BACKSPACE: [8],
47:     PLAY: [415, 179],
48:     PAUSE: [19],
49:     PLAY_PAUSE: [179],
50:     STOP: [413, 178],
51:     FAST_FORWARD: [417, 228],
52:     REWIND: [412, 227],
53:     COLOR_RED: [403],
54:     COLOR_GREEN: [404],
55:     COLOR_YELLOW: [405],
56:     COLOR_BLUE: [406]
57:   });
58: 
59:   var CONFIG = {
60:     activeClass: 'focused',
61:     tvFocusedClass: 'tv-focused',
62:     navigableSelector: '[data-nav="true"]',
63:     activeViewSelector: '.view.active',
64:     headerSelector: '.app-header',
65:     headerHiddenClass: 'header-hidden',
66:     orthogonalWeight: 2.5,
67:     overlapWeight: 1.5,
68:     maxOverlapBonus: 120,
69:     strictConeAngle: 60,   // degrees
70:     fallbackConeAngle: 85, // degrees
71:     epsilon: 4             // px tolerance
72:   };
73: 
74:   // ---------------------------------------------------------------------------
75:   // 2. Internal Engine State
76:   // ---------------------------------------------------------------------------
77:   var state = {
78:     initialized: false,
79:     enabled: true,
80:     currentFocus: null,
81:     previousFocus: null,
82:     activeTrap: null,
83:     viewMemory: {},
84:     listeners: {},
85:     lastMoveTimestamp: 0,
86:     rapidCount: 0,
87:     _keydownHandler: null
88:   };
89: 
90:   // ---------------------------------------------------------------------------
91:   // 3. Helper Functions
92:   // ---------------------------------------------------------------------------
93: 
94:   function normalizeDirection(dir) {
95:     if (!dir) return null;
96:     var d = String(dir).toLowerCase();
97:     if (d === 'arrowup' || d === 'up') return 'up';
98:     if (d === 'arrowdown' || d === 'down') return 'down';
99:     if (d === 'arrowleft' || d === 'left') return 'left';
100:     if (d === 'arrowright' || d === 'right') return 'right';
101:     return null;
102:   }
103: 
104:   function emit(eventName, payload) {
105:     var handlers = state.listeners[eventName];
106:     if (handlers && handlers.length) {
107:       for (var i = 0; i < handlers.length; i++) {
108:         try {
109:           handlers[i](payload);
110:         } catch (err) {
111:           console.error('[SpatialNav] Event error in ' + eventName + ':', err);
112:         }
113:       }
114:     }
115:   }
116: 
117:   function getCurrentViewName() {
118:     if (typeof document === 'undefined') return 'home';
119:     var activeView = document.querySelector(CONFIG.activeViewSelector);
120:     if (activeView && activeView.id) {
121:       return activeView.id.replace('view-', '');
122:     }
123:     return 'home';
124:   }
