126:   function resolveKeyAction(e) {
127:     if (!e) return null;
128:     var code = e.keyCode || e.which;
129:     var key = e.key || '';
130: 
131:     // D-Pad Navigation
132:     if (code === 38 || key === 'ArrowUp' || key === 'Up') return 'MOVE_UP';
133:     if (code === 40 || key === 'ArrowDown' || key === 'Down') return 'MOVE_DOWN';
134:     if (code === 37 || key === 'ArrowLeft' || key === 'Left') return 'MOVE_LEFT';
135:     if (code === 39 || key === 'ArrowRight' || key === 'Right') return 'MOVE_RIGHT';
136: 
137:     // Select / Enter
138:     if (code === 13 || key === 'Enter') return 'SELECT';
139: 
140:     // Back Navigation
141:     if (code === 461 || code === 27 || key === 'Escape' || key === 'Back' || key === 'XF86Back') {
142:       return 'BACK';
143:     }
144:     if (code === 8 || key === 'Backspace') return 'BACKSPACE';
145: 
146:     // Media Playback
147:     if (code === 415 || (code === 179 && key === 'MediaPlay') || key === 'Play') return 'MEDIA_PLAY';
148:     if (code === 19 || key === 'MediaPause' || key === 'Pause') return 'MEDIA_PAUSE';
149:     if (code === 179 || key === 'MediaPlayPause') return 'MEDIA_PLAY_PAUSE';
150:     if (code === 413 || code === 178 || key === 'MediaStop' || key === 'Stop') return 'MEDIA_STOP';
151:     if (code === 417 || code === 228 || key === 'MediaFastForward' || key === 'FastForward') return 'MEDIA_FAST_FORWARD';
152:     if (code === 412 || code === 227 || key === 'MediaRewind' || key === 'Rewind') return 'MEDIA_REWIND';
153: 
154:     // webOS Dedicated Color Keys
155:     if (code === 403 || key === 'ColorF0Red' || key === 'Red') return 'COLOR_RED';
156:     if (code === 404 || key === 'ColorF1Green' || key === 'Green') return 'COLOR_GREEN';
157:     if (code === 405 || key === 'ColorF2Yellow' || key === 'Yellow') return 'COLOR_YELLOW';
158:     if (code === 406 || key === 'ColorF3Blue' || key === 'Blue') return 'COLOR_BLUE';
159: 
160:     return null;
161:   }
162: 
163:   function shouldThrottleMovement() {
164:     var now = Date.now();
165:     var delta = now - state.lastMoveTimestamp;
166:     if (delta < CONSTANTS.THROTTLE_INTERVAL) {
167:       return true; // Discard event
168:     }
169:     if (delta < 120) {
170:       state.rapidCount++;
171:     } else {
172:       state.rapidCount = 0;
173:     }
174:     state.lastMoveTimestamp = now;
175:     return false;
176:   }
