178:   // ---------------------------------------------------------------------------
179:   // 4. Candidate Validation & Navigability Filter
180:   // ---------------------------------------------------------------------------
181: 
182:   function isNavigable(element) {
183:     if (!element || element.nodeType !== 1) return false;
184:     if (element.getAttribute('data-nav') === 'false') return false;
185: 
186:     // Disabled or aria-disabled/aria-hidden exclusions
187:     if (element.disabled || element.hasAttribute('disabled')) return false;
188:     if (element.getAttribute('aria-disabled') === 'true') return false;
189:     if (element.getAttribute('aria-hidden') === 'true') return false;
190: 
191:     // Document tree containment
192:     if (typeof document !== 'undefined' && !document.body.contains(element)) {
193:       return false;
194:     }
195: 
196:     // Modal / trap scope check
197:     if (state.activeTrap) {
198:       if (!state.activeTrap.contains(element)) return false;
199:     } else {
200:       // Inactive view exclusion: elements inside an inactive .view are excluded
201:       var parentView = element.closest('.view');
202:       if (parentView && !parentView.classList.contains('active')) {
203:         return false;
204:       }
205:     }
206: 
207:     // Geometry validation
208:     var rect = element.getBoundingClientRect();
209:     if (rect.width <= 0 || rect.height <= 0) return false;
210: 
211:     // Computed style check
212:     if (typeof window !== 'undefined' && window.getComputedStyle) {
213:       var style = window.getComputedStyle(element);
214:       if (style.display === 'none' || style.visibility === 'hidden' || style.opacity === '0') {
215:         return false;
216:       }
217:     }
218: 
219:     return true;
220:   }
221: 
222:   function getCandidates(scopeElement) {
223:     var candidates = [];
224:     var rootScope = scopeElement || state.activeTrap;
225: 
226:     if (rootScope) {
227:       var found = rootScope.querySelectorAll(CONFIG.navigableSelector);
228:       for (var i = 0; i < found.length; i++) {
229:         if (isNavigable(found[i])) candidates.push(found[i]);
230:       }
231:       return candidates;
232:     }
233: 
234:     if (typeof document === 'undefined') return candidates;
235: 
236:     // 1. Persistent Header items (if header is not hidden)
237:     var header = document.querySelector(CONFIG.headerSelector);
238:     if (header && !header.classList.contains(CONFIG.headerHiddenClass)) {
239:       var headerItems = header.querySelectorAll(CONFIG.navigableSelector);
240:       for (var h = 0; h < headerItems.length; h++) {
241:         if (isNavigable(headerItems[h])) candidates.push(headerItems[h]);
242:       }
243:     }
244: 
245:     // 2. Active View items
246:     var activeView = document.querySelector(CONFIG.activeViewSelector);
247:     if (activeView) {
248:       var viewItems = activeView.querySelectorAll(CONFIG.navigableSelector);
249:       for (var v = 0; v < viewItems.length; v++) {
250:         if (isNavigable(viewItems[v])) candidates.push(viewItems[v]);
251:       }
252:     }
253: 
254:     // 3. Test Sandbox items (if present in test harnesses)
255:     var sandbox = document.getElementById('test-spatial-sandbox');
256:     if (sandbox && !activeView?.contains(sandbox)) {
257:       var sbItems = sandbox.querySelectorAll(CONFIG.navigableSelector);
258:       for (var s = 0; s < sbItems.length; s++) {
259:         if (isNavigable(sbItems[s])) candidates.push(sbItems[s]);
260:       }
261:     }
262: 
263:     return candidates;
264:   }
265: 
266:   // ---------------------------------------------------------------------------
267:   // 5. 2D Spatial Distance & Scoring Algorithm
268:   // ---------------------------------------------------------------------------
269: 
270:   function computeGeometricScore(currentRect, candRect, direction, coneTan) {
271:     var R = currentRect;
272:     var C = candRect;
273: 
274:     var Rcx = R.left + R.width / 2;
275:     var Rcy = R.top + R.height / 2;
276:     var Ccx = C.left + C.width / 2;
277:     var Ccy = C.top + C.height / 2;
278: 
279:     var eps = CONFIG.epsilon;
280:     var dPrimary = 0;
281:     var dOrthogonal = 0;
282:     var deltaPrimary = 0;
283:     var deltaOrthogonal = 0;
284:     var orthOverlap = 0;
285: 
286:     if (direction === 'right') {
287:       // Must be positioned forward in +X
288:       if (C.left < R.right - eps && Ccx <= Rcx) return { qualified: false };
289:       deltaPrimary = Ccx - Rcx;
290:       deltaOrthogonal = Math.abs(Ccy - Rcy);
291:       if (deltaPrimary <= 0) return { qualified: false };
292:       if (coneTan && deltaOrthogonal > deltaPrimary * coneTan) return { qualified: false };
293: 
294:       dPrimary = (C.left >= R.right) ? (C.left - R.right) : Math.max(0, deltaPrimary * 0.5);
295:       orthOverlap = Math.max(0, Math.min(R.bottom, C.bottom) - Math.max(R.top, C.top));
296:       if (orthOverlap > 0) {
297:         dOrthogonal = deltaOrthogonal * 0.5;
298:       } else {
299:         var gapY = (C.top > R.bottom) ? (C.top - R.bottom) : (R.top - C.bottom);
300:         dOrthogonal = gapY + deltaOrthogonal * 0.5;
301:       }
302:     } else if (direction === 'left') {
303:       // Must be positioned forward in -X
304:       if (C.right > R.left + eps && Ccx >= Rcx) return { qualified: false };
305:       deltaPrimary = Rcx - Ccx;
306:       deltaOrthogonal = Math.abs(Ccy - Rcy);
307:       if (deltaPrimary <= 0) return { qualified: false };
308:       if (coneTan && deltaOrthogonal > deltaPrimary * coneTan) return { qualified: false };
309: 
310:       dPrimary = (R.left >= C.right) ? (R.left - C.right) : Math.max(0, deltaPrimary * 0.5);
311:       orthOverlap = Math.max(0, Math.min(R.bottom, C.bottom) - Math.max(R.top, C.top));
312:       if (orthOverlap > 0) {
313:         dOrthogonal = deltaOrthogonal * 0.5;
314:       } else {
315:         var gapY = (C.top > R.bottom) ? (C.top - R.bottom) : (R.top - C.bottom);
316:         dOrthogonal = gapY + deltaOrthogonal * 0.5;
317:       }
318:     } else if (direction === 'down') {
319:       // Must be positioned forward in +Y
320:       if (C.top < R.bottom - eps && Ccy <= Rcy) return { qualified: false };
321:       deltaPrimary = Ccy - Rcy;
322:       deltaOrthogonal = Math.abs(Ccx - Rcx);
323:       if (deltaPrimary <= 0) return { qualified: false };
324:       if (coneTan && deltaOrthogonal > deltaPrimary * coneTan) return { qualified: false };
325: 
326:       dPrimary = (C.top >= R.bottom) ? (C.top - R.bottom) : Math.max(0, deltaPrimary * 0.5);
327:       orthOverlap = Math.max(0, Math.min(R.right, C.right) - Math.max(R.left, C.left));
328:       if (orthOverlap > 0) {
329:         dOrthogonal = deltaOrthogonal * 0.5;
330:       } else {
331:         var gapX = (C.left > R.right) ? (C.left - R.right) : (R.left - C.right);
332:         dOrthogonal = gapX + deltaOrthogonal * 0.5;
333:       }
334:     } else if (direction === 'up') {
335:       // Must be positioned forward in -Y
336:       if (C.bottom > R.top + eps && Ccy >= Rcy) return { qualified: false };
337:       deltaPrimary = Rcy - Ccy;
338:       deltaOrthogonal = Math.abs(Ccx - Rcx);
339:       if (deltaPrimary <= 0) return { qualified: false };
340:       if (coneTan && deltaOrthogonal > deltaPrimary * coneTan) return { qualified: false };
341: 
342:       dPrimary = (R.top >= C.bottom) ? (R.top - C.bottom) : Math.max(0, deltaPrimary * 0.5);
343:       orthOverlap = Math.max(0, Math.min(R.right, C.right) - Math.max(R.left, C.left));
344:       if (orthOverlap > 0) {
345:         dOrthogonal = deltaOrthogonal * 0.5;
346:       } else {
347:         var gapX = (C.left > R.right) ? (C.left - R.right) : (R.left - C.right);
348:         dOrthogonal = gapX + deltaOrthogonal * 0.5;
349:       }
350:     } else {
351:       return { qualified: false };
352:     }
353: 
354:     var overlapBonus = Math.min(orthOverlap, CONFIG.maxOverlapBonus) * CONFIG.overlapWeight;
355:     var totalScore = dPrimary + (CONFIG.orthogonalWeight * dOrthogonal) - overlapBonus;
356:     var euclideanDist = Math.sqrt(deltaPrimary * deltaPrimary + deltaOrthogonal * deltaOrthogonal);
357: 
358:     return {
359:       qualified: true,
360:       score: totalScore,
361:       overlap: orthOverlap,
362:       euclidean: euclideanDist,
363:       dPrimary: dPrimary,
364:       dOrthogonal: dOrthogonal
365:     };
366:   }
367: 
368:   function findBestCandidate(currentElement, direction, candidates) {
369:     var dir = normalizeDirection(direction);
370:     if (!dir || !currentElement) return null;
371: 
372:     // Transitioning down from fixed header into the active view prefers the view's default anchor
373:     if (dir === 'down' && currentElement.closest && currentElement.closest(CONFIG.headerSelector)) {
374:       var activeView = document.querySelector(CONFIG.activeViewSelector);
375:       if (activeView) {
376:         var defaultEl = activeView.querySelector('[data-nav-default="true"]');
377:         if (defaultEl && isNavigable(defaultEl)) {
378:           return defaultEl;
379:         }
380:       }
381:     }
382: 
383:     var currentRect = currentElement.getBoundingClientRect();
384:     var list = candidates || getCandidates();
385:     if (!list || !list.length) return null;
386: 
387:     var strictTan = Math.tan((CONFIG.strictConeAngle * Math.PI) / 180);   // ~1.732 for 60 deg
388:     var fallbackTan = Math.tan((CONFIG.fallbackConeAngle * Math.PI) / 180); // ~11.43 for 85 deg
389: 
390:     // Pass 1: Strict Angle Cone (60 degrees)
391:     var best = null;
392:     var bestRes = null;
393: 
394:     for (var i = 0; i < list.length; i++) {
395:       var cand = list[i];
396:       if (cand === currentElement) continue;
397: 
398:       var candRect = cand.getBoundingClientRect();
399:       if (candRect.width <= 0 || candRect.height <= 0) continue;
400: 
401:       var res = computeGeometricScore(currentRect, candRect, dir, strictTan);
402:       if (res.qualified) {
403:         if (!bestRes || res.score < bestRes.score) {
404:           best = cand;
405:           bestRes = res;
406:         } else if (Math.abs(res.score - bestRes.score) < 1.0) {
407:           // Tie-breaking: Tier 1 Overlap -> Tier 2 Euclidean -> Tier 3 DOM Order
408:           if (res.overlap > bestRes.overlap) {
409:             best = cand;
410:             bestRes = res;
411:           } else if (res.overlap === bestRes.overlap) {
412:             if (res.euclidean < bestRes.euclidean) {
413:               best = cand;
414:               bestRes = res;
415:             } else if (res.euclidean === bestRes.euclidean) {
416:               if (currentElement.compareDocumentPosition &&
417:                   (best.compareDocumentPosition(cand) & Node.DOCUMENT_POSITION_PRECEDING)) {
418:                 best = cand;
419:                 bestRes = res;
420:               }
421:             }
422:           }
423:         }
424:       }
425:     }
426: 
427:     if (best) return best;
428: 
429:     // Pass 2: Fallback Cone (85 degrees)
430:     for (var j = 0; j < list.length; j++) {
431:       var cand2 = list[j];
432:       if (cand2 === currentElement) continue;
433: 
434:       var candRect2 = cand2.getBoundingClientRect();
435:       if (candRect2.width <= 0 || candRect2.height <= 0) continue;
436: 
437:       var res2 = computeGeometricScore(currentRect, candRect2, dir, fallbackTan);
438:       if (res2.qualified) {
439:         if (!bestRes || res2.score < bestRes.score) {
440:           best = cand2;
441:           bestRes = res2;
442:         } else if (Math.abs(res2.score - bestRes.score) < 1.0) {
443:           if (res2.overlap > bestRes.overlap) {
444:             best = cand2;
445:             bestRes = res2;
446:           } else if (res2.overlap === bestRes.overlap && res2.euclidean < bestRes.euclidean) {
447:             best = cand2;
448:             bestRes = res2;
449:           }
450:         }
451:       }
452:     }
453: 
454:     return best;
455:   }
