457:   // ---------------------------------------------------------------------------
458:   // 6. Two-Tier TV-Safe Auto-Scroll Subsystem
459:   // ---------------------------------------------------------------------------
460: 
461:   function autoScrollShelf(element) {
462:     if (!element) return;
463:     var rail = element.closest('.shelf-rail, .cards-carousel, [data-scroll-rail="true"]');
464:     if (!rail) return;
465: 
466:     var behavior = state.rapidCount > 2 ? 'auto' : 'smooth';
467: 
468:     // Case 1: First element reset
469:     if (!element.previousElementSibling || element.getAttribute('data-nav-index') === '0') {
470:       if (rail.scrollLeft !== 0) {
471:         rail.scrollTo({ left: 0, behavior: behavior });
472:       }
473:       return;
474:     }
475: 
476:     var rect = element.getBoundingClientRect();
477:     var current = rail.scrollLeft || 0;
478: 
479:     // Case 2: Clipped on Left (< 96px)
480:     if (rect.left < CONSTANTS.SAFE_X_MIN) {
481:       var dLeft = CONSTANTS.SAFE_X_MIN - rect.left;
482:       rail.scrollTo({ left: Math.max(0, current - dLeft), behavior: behavior });
483:       return;
484:     }
485: 
486:     // Case 3: Clipped on Right (> 1824px)
487:     if (rect.right > CONSTANTS.SAFE_X_MAX) {
488:       var dRight = rect.right - CONSTANTS.SAFE_X_MAX;
489:       var targetRight = current + dRight + CONSTANTS.PEEK_OFFSET;
490:       if (rail.scrollWidth > rail.clientWidth && rail.clientWidth > 0) {
491:         targetRight = Math.min(rail.scrollWidth - rail.clientWidth, targetRight);
492:       }
493:       rail.scrollTo({ left: targetRight, behavior: behavior });
494:       return;
495:     }
496:   }
