498:   function autoScrollViewport(element) {
499:     if (!element) return;
500: 
501:     // Header items reset viewport to top
502:     if (element.closest(CONFIG.headerSelector)) {
503:       var activePane = document.querySelector(CONFIG.activeViewSelector + ' .view-scroll-pane');
504:       if (activePane && activePane.scrollTop !== 0) {
505:         activePane.scrollTo({ top: 0, behavior: 'smooth' });
506:       }
507:       return;
508:     }
509: 
510:     var pane = element.closest('.view-scroll-pane');
511:     if (!pane) return;
512: 
513:     var behavior = state.rapidCount > 2 ? 'auto' : 'smooth';
514: 
515:     // Hero banner items reset viewport to top
516:     if (element.closest('.hero-banner')) {
517:       if (pane.scrollTop !== 0) {
518:         pane.scrollTo({ top: 0, behavior: behavior });
519:       }
520:       return;
521:     }
522: 
523:     var currentY = pane.scrollTop || 0;
524:     var shelf = element.closest('.content-shelf');
525: 
526:     if (shelf) {
527:       var shelfRect = shelf.getBoundingClientRect();
528:       var cardRect = element.getBoundingClientRect();
529: 
530:       // Sub-case 3a: Shelf or card occluded by fixed header (< 104px)
531:       var effectiveTop = Math.min(shelfRect.top, cardRect.top);
532:       if (effectiveTop < CONSTANTS.EFFECTIVE_Y_MIN) {
533:         var dUp = CONSTANTS.EFFECTIVE_Y_MIN - effectiveTop;
534:         pane.scrollTo({ top: Math.max(0, currentY - dUp), behavior: behavior });
535:         return;
536:       }
537: 
538:       // Sub-case 3b: Card bottom clipped past TV safe boundary (> 1026px)
539:       if (cardRect.bottom > CONSTANTS.SAFE_Y_MAX) {
540:         var dDown = cardRect.bottom - CONSTANTS.SAFE_Y_MAX;
541:         pane.scrollTo({ top: currentY + dDown + 36, behavior: behavior });
542:         return;
543:       }
544:       return;
545:     }
546: 
547:     // Generic grid or list item
548:     var itemRect = element.getBoundingClientRect();
549:     if (itemRect.top < CONSTANTS.EFFECTIVE_Y_MIN) {
550:       var diffTop = CONSTANTS.EFFECTIVE_Y_MIN - itemRect.top;
551:       pane.scrollTo({ top: Math.max(0, currentY - diffTop - 24), behavior: behavior });
552:     } else if (itemRect.bottom > CONSTANTS.SAFE_Y_MAX) {
553:       var diffBottom = itemRect.bottom - CONSTANTS.SAFE_Y_MAX;
