309: function createHarness(options) {
310:   var opts = options || {};
311:   var initialRoute = opts.initialRoute || 'home';
312:   var customRoutes = opts.mockRoutes || {};
313: 
314:   var projectRoot = path.resolve(__dirname, '..');
315:   var htmlPath = path.resolve(projectRoot, 'app/index.html');
316:   var configPath = path.resolve(projectRoot, 'app/js/config.js');
317:   var navPath = path.resolve(projectRoot, 'app/js/navigation.js');
318:   var tmdbPath = path.resolve(projectRoot, 'app/js/tmdb.js');
319:   var homePath = path.resolve(projectRoot, 'app/js/views/home.js');
320:   var catalogPath = path.resolve(projectRoot, 'app/js/views/catalog.js');
321:   var searchPath = path.resolve(projectRoot, 'app/js/views/search.js');
322:   var detailsPath = path.resolve(projectRoot, 'app/js/views/details.js');
323:   var appPath = path.resolve(projectRoot, 'app/js/app.js');
324: 
325:   var html = fs.readFileSync(htmlPath, 'utf8');
326:   var dom = new JSDOM(html, {
327:     url: 'http://localhost/#' + initialRoute,
328:     runScripts: 'outside-only'
329:   });
330:   var window = dom.window;
331: 
332:   installScrollMocks(window);
333:   installLayoutMock(window);
334: 
335:   var routes = Object.assign({}, BASE_ROUTES, customRoutes);
336:   window._fetchCalls = [];
337:   var sortedPatterns = Object.keys(routes).sort((a, b) => b.length - a.length);
338: 
339:   window.fetch = function (url, fetchOpts) {
340:     var urlStr = String(url);
341:     window._fetchCalls.push({ url: urlStr, options: fetchOpts || {} });
342: 
343:     for (var i = 0; i < sortedPatterns.length; i++) {
344:       var pat = sortedPatterns[i];
345:       if (urlStr.indexOf(pat) !== -1) {
346:         var h = routes[pat];
347:         var res = typeof h === 'function' ? h(urlStr, fetchOpts) : h;
348: 
349:         if (res && res._delayMs) {
350:           return new Promise(function (resolve) {
351:             setTimeout(function () {
352:               resolve({
353:                 ok: !res._error,
354:                 status: res._error ? 500 : 200,
355:                 statusText: res._error ? 'Server Error' : 'OK',
356:                 json: function () {
357:                   return res._error ? Promise.reject(new Error('Server Error')) : Promise.resolve(JSON.parse(JSON.stringify(res.data || res)));
358:                 }
359:               });
360:             }, res._delayMs);
361:           });
362:         }
363: 
364:         if (res && res._error) {
365:           return Promise.resolve({
366:             ok: false,
367:             status: 500,
368:             statusText: 'Internal Error',
369:             json: function () { return Promise.reject(new Error('Internal Error')); }
370:           });
371:         }
372: 
373:         return Promise.resolve({
374:           ok: true,
375:           status: 200,
376:           statusText: 'OK',
377:           json: function () { return Promise.resolve(JSON.parse(JSON.stringify(res))); }
378:         });
379:       }
380:     }
381: 
382:     return Promise.resolve({
383:       ok: false,
384:       status: 404,
385:       statusText: 'Not Found',
386:       json: function () { return Promise.resolve({ error: true }); }
387:     });
388:   };
389: 
390:   window.eval(fs.readFileSync(configPath, 'utf8'));
391:   window.eval(fs.readFileSync(navPath, 'utf8'));
392:   window.eval(fs.readFileSync(tmdbPath, 'utf8'));
393:   window.eval(fs.readFileSync(homePath, 'utf8'));
394:   window.eval(fs.readFileSync(catalogPath, 'utf8'));
395:   window.eval(fs.readFileSync(searchPath, 'utf8'));
396:   window.eval(fs.readFileSync(detailsPath, 'utf8'));
397:   window.eval(fs.readFileSync(appPath, 'utf8'));
398: 
399:   if (window.CinejoyApp && typeof window.CinejoyApp.init === 'function') {
400:     window.CinejoyApp.init();
401:   }
402: 
403:   return {
404:     dom: dom,
405:     window: window,
406:     document: window.document,
407:     app: window.CinejoyApp,
408:     nav: window.SpatialNav,
409:     tmdb: window.TmdbClient,
410:     home: window.HomeViewController,
411:     movies: window.MoviesViewController,
412:     series: window.SeriesViewController,
413:     search: window.SearchViewController,
414:     details: window.DetailsViewController
415:   };
416: }
