## 5. Concrete Hardening Recommendations & Proposed Code

### Proposal 1: Hardened Stack-Based Trap & Trapped Self-Healing in `app/js/navigation.js`

```javascript
// Proposed additions to app/js/navigation.js

// 1. Internal state enhancement (around line 82)
var state = {
  initialized: false,
  enabled: true,
  currentFocus: null,
  previousFocus: null,
  activeTrap: null,
  _trapStack: [], // Stack-based trap history: [{ container, trigger, fallback }]
  viewMemory: {},
  listeners: {},
  lastMoveTimestamp: 0,
  rapidCount: 0,
  _keydownHandler: null
};

// 2. Trapped self-healing enhancement in move() (around line 758)
function move(direction, event) {
  if (!state.enabled) return null;

  var current = state.currentFocus;

  // Self-healing: if current focus is detached or null, recover
  if (!current || !document.body.contains(current)) {
    var recovered = null;

    // Priority 1: If active trap engaged, self-heal strictly within the trap
    if (state.activeTrap && document.body.contains(state.activeTrap)) {
      var trapCandidates = getCandidates(state.activeTrap);
      if (trapCandidates && trapCandidates.length > 0) {
        recovered = trapCandidates[0];
        setFocus(recovered);
      }
    }

    // Priority 2: Standard view memory restoration
    if (!recovered) {
      recovered = restoreFocus(getCurrentViewName());
    }

    if (recovered) {
      state.currentFocus = recovered;
      current = recovered;
    } else {
      return null;
    }
  }

  var best = findBestCandidate(current, direction);
  // ... rest of move()
}

// 3. Stack-aware trap() and untrap() with trigger caching (around line 964)
trap: function (container, options) {
  var el = (typeof container === 'string') ? document.querySelector(container) : container;
  if (!el) return false;

  var opts = options || {};
  var trigger = opts.triggerElement || state.currentFocus;
  var fallback = opts.fallback || null;

  state._trapStack.push({
    container: el,
    triggerElement: trigger,
    fallback: fallback
  });

  state.activeTrap = el;
  emit('trap', { container: el, triggerElement: trigger });
  return true;
},

untrap: function (options) {
  var opts = options || {};
  var currentTrapInfo = state._trapStack.pop();
  var prevContainer = currentTrapInfo ? currentTrapInfo.container : state.activeTrap;

  // Restore previous trap if nested
  if (state._trapStack.length > 0) {
    var parentTrap = state._trapStack[state._trapStack.length - 1];
    state.activeTrap = parentTrap.container;
  } else {
    state.activeTrap = null;
  }

  emit('untrap', { container: prevContainer, remainingTraps: state._trapStack.length });

  // Optional automatic focus restoration to trigger
  if (opts.restoreFocus && currentTrapInfo) {
    var target = currentTrapInfo.triggerElement;
    var restored = false;
    if (target && document.body.contains(target) && isNavigable(target)) {
      restored = setFocus(target);
    }
    if (!restored && currentTrapInfo.fallback) {
      var fb = currentTrapInfo.fallback;
      if (typeof fb === 'string') fb = document.querySelector(fb);
      if (fb && isNavigable(fb)) {
        restored = setFocus(fb);
      }
    }
    if (!restored) {
      restoreFocus(getCurrentViewName());
    }
  }

  return currentTrapInfo;
},

getTrapTrigger: function () {
  if (state._trapStack.length > 0) {
    return state._trapStack[state._trapStack.length - 1].triggerElement;
  }
  return null;
}
```

### Proposal 2: Search Keyboard Re-Entry Trap Auto-Engagement in `app/js/views/search.js`

```javascript
// In app/js/views/search.js (inside bindKeyboard, around line 86)

// Auto-engage trap whenever focus enters any button in the virtual keyboard
if (global.SpatialNav && typeof global.SpatialNav.on === 'function') {
  global.SpatialNav.on('focus', function (data) {
    if (!data || !data.element || !self.keyboard) return;
    var curView = (global.CinejoyApp && global.CinejoyApp.state && global.CinejoyApp.state.currentView) || 'search';
    if (curView === 'search') {
      if (self.keyboard.contains(data.element)) {
        if (!self.isTrapped) {
          self.engageTrap();
        }
      } else {
        if (self.isTrapped) {
          self.releaseTrap();
        }
      }
    }
  });
}
```

### Proposal 3: Robust Cascading Restoration in `app/js/player.js`

```javascript
// In app/js/player.js (closeActiveModal, around line 1884)
closeActiveModal: function () {
  var d = this._dom;
  if (d.subsModal) d.subsModal.style.display = 'none';
  if (d.serverModal) d.serverModal.style.display = 'none';
  if (d.errorDialog) d.errorDialog.style.display = 'none';

  var closed = this._activeModal;
  this._activeModal = null;

  if (global.SpatialNav) {
    global.SpatialNav.untrap();

    var restored = false;
    if (closed === d.subsModal && d.subtitlesBtn) {
      restored = global.SpatialNav.setFocus(d.subtitlesBtn);
    } else if (closed === d.serverModal && d.serverBtn) {
      restored = global.SpatialNav.setFocus(d.serverBtn);
    }

    // Cascading fallback tier 1: Play button
    if (!restored && d.playBtn) {
      restored = global.SpatialNav.setFocus(d.playBtn);
    }

    // Cascading fallback tier 2: View memory or first navigable in player view
    if (!restored) {
      global.SpatialNav.restoreFocus('player');
    }
  }

  this.resetIdleTimer();
}
```

